using UnityEngine;
namespace Crownfall.StatusEffects { public enum StatusType{Burn,Poison,Stun,Root,Silence,Disarm,Slow,ArmorBreak,MagicResistBreak,Wound,AttackBuff,AttackSpeedBuff,Taunt} public enum StatusStackRule{RefreshDuration,StackIntensity,StackDuration,Independent,Replace,Ignore} [CreateAssetMenu(fileName="Status",menuName="Crownfall/Status/Definition")] public sealed class StatusDefinition:ScriptableObject { public string statusId; public StatusType type; [Min(.05f)]public float duration=3; public StatusStackRule stackRule=StatusStackRule.RefreshDuration; [Min(1)]public int maxStacks=1; public bool periodic; [Min(.05f)]public float tickInterval=1; public float flatDamage; public float sourceAttackScaling; } }
